export function nextGeneration(livingCells: Cell[]): Cell[] {
  return livingCells.filter(([x, y]) => {
    const neighbourCount = livingCells.filter(
      ([otherX, otherY]) =>
        Math.abs(otherX - x) <= 1 &&
        Math.abs(otherY - y) <= 1 &&
        !(otherX === x && otherY === y),
    ).length;
    return neighbourCount === 2 || neighbourCount === 3;
  });
}

